    [Xunit.Fact]
    public static void TestInsertionNeedsConfidence700() {
        emon.Testport.AssertEq(Ofuse.OfRule(0, 0, 0, 0, 0, 2, 0, 699, 0), 0, "agreement does not bypass insertion floor");
        emon.Testport.AssertEq(Ofuse.OfRule(0, 0, 0, 0, 0, 2, 0, 700, 0), 3, "700 inserts");
        emon.Testport.AssertEq(Ofuse.OfRule(0, 0, 0, 0, 1, 1, 0, 700, 0), 3, "dictionary permits single-reading alpha insertion");
        emon.Testport.AssertEq(Ofuse.OfRule(0, 1, 0, 1, 0, 1, 0, 700, 0), 3, "format permits single-reading numeric insertion");
    }
