        emon.Port.Cells parents = emon.Port.NewCells();
        emon.Port.Cells sorted = emon.Port.NewCells();
        Evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(words, 1, 50, 0, 150, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(words, 1, 100, 0, 200, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(words, 1, 151, 0, 251, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        emon.Port.CellsPush(rows, 0);
        emon.Port.CellsPush(rows, 1);
        emon.Port.CellsPush(rows, 2);
        emon.Port.CellsPush(rows, 3);
        Ofuse.OfAlign(words, rows, parents, sorted);
        emon.Testport.AssertEq(Ofuse.OfRoot(parents, 0), Ofuse.OfRoot(parents, 2), "half-overlap chain is one slot");
        emon.Testport.AssertEq(Ofuse.OfRoot(parents, 3), 3, "49 percent overlap stays separate");
    }
    [Xunit.Fact]
    public static void TestSlotsNeverLinkDifferentPages() {
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells rows = emon.Port.NewCells();
        emon.Port.Cells parents = emon.Port.NewCells();
        emon.Port.Cells sorted = emon.Port.NewCells();
        Evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(words, 2, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        emon.Port.CellsPush(rows, 0);
        emon.Port.CellsPush(rows, 1);
        Ofuse.OfAlign(words, rows, parents, sorted);
        emon.Testport.AssertEq(Ofuse.OfRoot(parents, 0), 0, "page one");
        emon.Testport.AssertEq(Ofuse.OfRoot(parents, 1), 1, "page two");
    }
    [Xunit.Fact]
    public static void TestOversizedAndEmptyBoxesDoNotChainSlots() {
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells rows = emon.Port.NewCells();
        emon.Port.Cells parents = emon.Port.NewCells();
        emon.Port.Cells sorted = emon.Port.NewCells();
        Evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(words, 1, 200, 0, 300, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(words, 1, 0, 0, 10000, 10000, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(words, 1, 0, 0, 0, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        emon.Port.CellsPush(rows, 0);
        emon.Port.CellsPush(rows, 1);
        emon.Port.CellsPush(rows, 2);
        emon.Port.CellsPush(rows, 3);
        Ofuse.OfAlign(words, rows, parents, sorted);
        emon.Testport.AssertEq(Ofuse.OfRoot(parents, 0), 0, "first word stays independent");
        emon.Testport.AssertEq(Ofuse.OfRoot(parents, 1), 1, "second word stays independent");
        emon.Testport.AssertEq(Ofuse.OfRoot(parents, 2), -1, "giant box cannot bridge words");
        emon.Testport.AssertEq(Ofuse.OfRoot(parents, 3), -1, "empty box is excluded");
    }
    [Xunit.Fact]
    public static void TestEqualBoxPermutationDoesNotChangeSlotMembership() {
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells rows = emon.Port.NewCells();
        emon.Port.Cells parents = emon.Port.NewCells();
        emon.Port.Cells sorted = emon.Port.NewCells();
        Evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        Evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
        emon.Port.CellsPush(rows, 1);
        emon.Port.CellsPush(rows, 0);
        Ofuse.OfAlign(words, rows, parents, sorted);
        emon.Testport.AssertEq(Ofuse.OfRoot(parents, 0), Ofuse.OfRoot(parents, 1), "reverse source order links the same source rows");
    }
