    [Xunit.Fact]
    public static void TestFormatSpanBoundsDoNotOverflowOrReadOutsideRecordedText() {
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.CellsPush(text, 49);
        emon.Testport.AssertEq(Ofmt.OfmtValid(text, -1, 1), 0, "negative start");
        emon.Testport.AssertEq(Ofmt.OfmtValid(text, 0, 2), 0, "long span");
        emon.Testport.AssertEq(Ofmt.OfmtValid(text, 2147483647, 2147483647), 0, "hostile overflowing span");
        emon.Testport.AssertEq(Ofmt.OfmtValid(text, 0, 1), 1, "recorded digit");
    }
